mapper.insert:
INSERT INTO collection_members (
    collection_id
,   user_id
,   role
) VALUES (
    #{collectionId}
,   #{userId}
,   #{role}
)
ON DUPLICATE KEY UPDATE role = role

mapper.update:
UPDATE  collection_members
SET     role = #{role}
WHERE   collection_id = #{collectionId}
AND     user_id = #{userId}

mapper.delete:
DELETE FROM collection_members
WHERE       collection_id = #{collectionId}
AND         user_id = #{userId}

mapper.select:
SELECT  role
FROM    collection_members
WHERE   collection_id = #{collectionId}
AND     user_id = #{userId}
